WHERE t1.deleted = 0

    AND t1.order_id = #{reqVO.orderId}


    AND t1.order_structure_id = #{reqVO.orderStructureId}


    AND t4.customer_id = #{reqVO.customerId}


    AND t2.version_id = #{reqVO.versionId}


    AND t1.product_id = #{reqVO.productId}


    AND t1.spec = #{reqVO.spec}


    AND t1.element_id = #{reqVO.elementId}


    AND t1.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
